from pathlib import Path
import json
root=Path("E:/WebAIBridge/app")
out={"app_exists":root.is_dir(),"sample_files":[],"matches":[]}
if root.is_dir():
 count=0
 for p in root.rglob("*"):
  if not p.is_file() or p.suffix.lower() not in (".js",".mjs",".ts",".cjs",".tsx"):continue
  if any(x in p.parts for x in ("node_modules",".git","dist","build",".next")):continue
  count+=1
  if len(out["sample_files"])<25:out["sample_files"].append(str(p.relative_to(root)))
  if p.stat().st_size>3_000_000:continue
  try:
   s=p.read_text(encoding="utf-8",errors="replace")
   if "/agent-assignments" in s or "allowAutonomousSend" in s:
    out["matches"].append({"path":str(p.relative_to(root)),"contains_assignment":"/agent-assignments" in s,"contains_autonomous_gate":"allowAutonomousSend" in s})
  except Exception:pass
  if count>=1000:break
 out["scanned_files"]=count
print(json.dumps(out,ensure_ascii=True))
